    listResources: {
        parameters: {
            query?: {
                /** @description Restrict to these states; repeat the parameter to pass several. Omitted means all of them. For a USER the result is always intersected with the non-FAILED states (see above). */
                status?: ("AWAITING_UPLOAD" | "SCANNING" | "READING" | "BUILDING" | "READY" | "FAILED")[];
                /**
                 * @description Keyword search: restrict to resources whose TITLE contains this, case-insensitively. Blank or omitted means all of them.
                 *
                 *     It NARROWS rather than replaces - it composes with `status`, with the USER rule above, with the org scope and with the trash exclusion, so no search reaches anything the plain listing would not have shown.
                 *
                 *     `%` and `_` match THEMSELVES; they are not wildcards to the caller.
                 *
                 *     Searching inside a document's content is a different question answered by meaning rather than substring. It is served for ONE lecture at a time by `POST /o/{orgId}/resources/{resourceId}/search`. An org-wide search inside content still does not exist: it has no single version to authorise against and no per-document bound on its cost, and is tracked separately.
                 *
                 *     The length ceiling is measured on what you SEND, before the api trims surrounding whitespace - so a 100-character term padded with a space is 101 characters and is refused.
                 */
                q?: string;
                /** @description Zero-based page index */
                page?: number;
                /** @description Page size; capped so a caller cannot request an unbounded page */
                size?: number;
            };
            header?: never;
            path: {
                /** @description The organisation's id */
                orgId: string;
            };
            cookie?: never;
        };
        requestBody?: never;
        responses: {
            /** @description One page of the library */
            200: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": components["schemas"]["ResourceListResponse"];
                };
            };
            /** @description An out-of-range page or size, or a search term over 100 characters */
            400: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/problem+json": components["schemas"]["Problem"];
                };
            };
            /** @description Missing/unusable access token (`ATLAS-SYS-002`) */
            401: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/problem+json": components["schemas"]["Problem"];
                };
            };
            /** @description Not a member / no such org (`ATLAS-ORG-002`, no existence oracle) */
            403: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/problem+json": components["schemas"]["Problem"];
                };
            };
            429: components["responses"]["Throttled"];
            500: components["responses"]["InternalError"];
        };
    };
